import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import {pathToFileURL} from 'node:url';

const BASE={en:'https://dgroupapp-luke-acts.eicparis.org/',es:'https://cnartatez-lgtm.github.io/dgroups-lucas-hechos-es/'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=p=>JSON.parse(fs.readFileSync(p,'utf8').replace(/^\uFEFF/,''));
const json=d=>JSON.stringify(d).replace(/</g,'\\u003c');
const strip=s=>String(s).replace(/\s+/g,' ').trim();
const texts={en:{title:'Luke and Acts Bible Study & Devotionals | D-Groups',heading:'Luke and Acts Bible Study & Devotionals',description:'Study Luke and Acts with weekly Bible readings, pastoral devotionals, reflection questions and study tools. From Bethlehem to the Nations, by EIC Paris.',summary:'About this Luke–Acts devotional study',overview:'From Bethlehem to the Nations is a free Bible study for personal reflection and small groups. Read Scripture, explore its context and talk through observation, interpretation and application, with pastoral commentary from EIC Paris.',library:'Published devotionals',intro:'Read the pastoral reflections that are available so far, then continue the weekly study in the app. New commentaries join this collection when their study week opens.',back:'Continue in the study app',home:'Study home',by:'Pastoral notes by Associate Pastor Christian Nartatez, EIC Rueil-Malmaison, under the supervision of the Senior Pastors of EIC Paris.',reflection:'Reflection question',optional:'Optional Ideas to Explore'},es:{title:'Devocionales y estudio bíblico de Lucas y Hechos | D-Groups',heading:'Devocionales y estudio bíblico de Lucas y Hechos',description:'Estudia Lucas y Hechos con lecturas bíblicas semanales, devocionales pastorales, preguntas para reflexionar y herramientas de estudio. Un recorrido de EIC Paris.',summary:'Sobre este devocional de Lucas–Hechos',overview:'De Belén a las naciones es un estudio bíblico gratuito para la reflexión personal y los grupos pequeños. Lee la Biblia, explora su contexto y conversa sobre observación, interpretación y aplicación, con comentarios pastorales de EIC Paris.',library:'Devocionales publicados',intro:'Lee las reflexiones pastorales que ya están disponibles y continúa el estudio semanal en la aplicación. Los nuevos comentarios se añaden cuando comienza la semana que les corresponde.',back:'Continuar en la aplicación de estudio',home:'Inicio del estudio',by:'Notas pastorales del pastor asociado Christian Nartatez, EIC Rueil-Malmaison, bajo la supervisión de los pastores principales de EIC Paris.',reflection:'Pregunta para reflexionar',optional:'Ideas opcionales para explorar'}};

function alternates(relative){return Object.entries(BASE).map(([lang,base])=>`<link rel="alternate" hreflang="${lang}" href="${base+relative}">`).join('\n');}
function schema(locale,url,title,description,type='WebSite',image){return {'@context':'https://schema.org','@type':type,'@id':url+'#'+type.toLowerCase(),url,name:title,...(type==='Article'?{headline:title,author:{'@type':'Person',name:'Christian Nartatez',jobTitle:'Associate Pastor'}}:{}),description,inLanguage:locale,publisher:{'@type':'Organization',name:'EIC Paris',url:'https://eicparis.org/'},...(image?{image}:{} )};}
function meta(locale,relative,title,description,type='WebSite',image){const base=BASE[locale],url=base+relative;image??=base+`assets/share-${locale}-20261011.jpg`;return `<link rel="canonical" href="${url}">\n${alternates(relative)}\n<meta name="robots" content="index, follow, max-image-preview:large">\n<meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${url}"><meta property="og:type" content="${type==='Article'?'article':'website'}"><meta property="og:image" content="${image}"><meta property="og:locale" content="${locale==='es'?'es_ES':'en_GB'}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${esc(title)}"><meta name="twitter:description" content="${esc(description)}"><meta name="twitter:image" content="${image}">\n<script type="application/ld+json">${json(schema(locale,url,title,description,type,image))}</script>`;}
function paragraphs(text){return String(text||'').split(/\n+/).filter(Boolean).map(p=>{
 const label=p.trim();if(/^(?:Before You Begin|Antes de comenzar):?$/i.test(label))return `<h2>${esc(label)}</h2>`;if(/^(?:Reflection Questions?|Preguntas? para reflexionar):?$/i.test(label))return `<h3>${esc(label)}</h3>`;
 if(/^(?:Optional Ideas to Explore|Ideas opcionales para explorar):?$/i.test(label))return `<h3><em>${esc(label)}</em></h3>`;
 return '<p>'+esc(p).replace(/\n/g,'<br>')+'</p>';
 }).join('\n');}
const CSS=`.reading-document{color-scheme:light;--bg:#f7f5f1;--paper:#fffdfa;--ink:#2c2926;--muted:#625b56;--accent:#942e42;--line:#e1d9d1}.reading-document *{box-sizing:border-box}body.reading-document{margin:0;background:var(--bg);color:var(--ink);font:18px/1.8 system-ui,sans-serif}main.reading-page{max-width:800px;margin:auto;padding:24px 24px 64px}.reading-page h1,.reading-page h2,.reading-page h3{font-family:Georgia,serif;line-height:1.25;text-wrap:balance}.reading-page h1{font-size:clamp(30px,6vw,44px)}.reading-page h2{font-size:28px;margin-top:40px}.reading-page h3{font-size:23px;margin-top:30px}.reading-page p{overflow-wrap:anywhere}.reading-page a{color:var(--accent);text-underline-offset:4px}.reading-page a{min-height:44px;display:inline-flex;align-items:center}.reading-page header{border-bottom:1px solid var(--line);margin-bottom:28px;padding-bottom:20px}.reading-page nav{display:flex;gap:12px;flex-wrap:wrap;align-items:center;font-size:15px}.reading-page figure{margin:28px 0}.reading-page img{width:100%;height:auto;border-radius:10px}.reading-page .byline,.reading-page .passage{color:var(--muted);font-size:15px}.reading-page article{margin:24px 0;padding:4px 0 24px;border-bottom:1px solid var(--line)}.reading-page li{padding:8px 0}.search-overview{margin:26px 0;padding:16px 20px;border:1px solid var(--line);border-radius:9px;background:var(--surface,var(--paper));line-height:1.8}.search-overview summary{cursor:pointer;min-height:44px;display:list-item;padding:9px 0;font-weight:600}.search-overview p{font-size:16px}.search-overview a{display:inline-flex;align-items:center;min-height:44px}.reading-page a:focus-visible,.search-overview summary:focus-visible{outline:3px solid var(--accent);outline-offset:4px}@media(max-width:480px){main.reading-page{padding:18px 18px 48px}body.reading-document{font-size:17px}.search-overview{padding:12px 16px}}@media(prefers-color-scheme:dark){.reading-document{--bg:#1d1b1a;--paper:#242120;--ink:#f3ece6;--muted:#c4b8ad;--accent:#ef9cac;--line:#514841}}`;
function page(locale,relative,title,description,body,type='CollectionPage',image){return `<!doctype html>\n<html lang="${locale}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><title>${esc(title)}</title><meta name="description" content="${esc(description)}">${meta(locale,relative,title,description,type,image)}<link rel="icon" href="${BASE[locale]}favicon.ico"><link rel="stylesheet" href="${BASE[locale]}discovery.css"></head><body class="reading-document"><main class="reading-page"><header><nav aria-label="${locale==='es'?'Ubicación':'Location'}"><a href="${BASE[locale]}#introduction">${texts[locale].home}</a><span aria-hidden="true">/</span><a href="${BASE[locale]}devotionals/">${texts[locale].library}</a></nav></header>${body}<footer><p class="byline">${texts[locale].by}</p><a href="${BASE[locale]}#studies">${texts[locale].back} →</a></footer></main></body></html>\n`;}

export function buildDiscovery(root,now=Date.now()){
 root=path.resolve(root);const index=fs.readFileSync(path.join(root,'index.html'),'utf8');const locale=/<html[^>]*lang="es"/.test(index)?'es':'en',t=texts[locale],base=BASE[locale];
 const catalog=read(path.join(root,'published/catalog.json'));const lessons=catalog.lessons.filter(l=>l.status==='available'&&Date.parse(l.commentaryReleaseAt||l.releaseAt)<=now);
 const directory=path.join(root,'devotionals');fs.mkdirSync(directory,{recursive:true});const links=[],urls=['','devotionals/'];
 for(const entry of lessons){
  const folder=path.join(root,'published',entry.id);assert.ok(fs.existsSync(path.join(folder,'lesson.json')));const lesson=read(path.join(folder,'lesson.json'));const relative=`devotionals/week-${String(entry.number).padStart(2,'0')}/`;urls.push(relative);
  const image=lesson.points.find(p=>p.image);const imageURL=image?base+'published/'+entry.id+'/'+image.image:undefined;
  const description=locale==='es'?`Devocional y comentario pastoral de ${entry.passage}: ${lesson.title}. Lectura para reflexionar y estudiar en grupo con EIC Paris.`:`Devotional and pastoral Bible commentary on ${entry.passage}: ${lesson.title}. Reflect and study together with EIC Paris.`;
  const body=`<h1>${esc(lesson.title)}</h1><p class="passage">${esc(entry.passage)}</p>${image?`<figure><img src="${imageURL}" alt="${esc(image.alt)}" width="1774" height="887" decoding="async" fetchpriority="high"></figure>`:''}${paragraphs(lesson.introduction)}${lesson.points.map(p=>`<section><h2>${esc(p.title)}</h2><p class="passage">${esc(p.reference)}</p>${p!==image&&p.image?`<figure><img src="${base+'published/'+entry.id+'/'+p.image}" alt="${esc(p.alt)}" loading="lazy" width="1774" height="887"></figure>`:''}${paragraphs(p.text)}</section>`).join('')}${lesson.finalWord?paragraphs(lesson.finalWord):''}`;
  const dest=path.join(root,relative);fs.mkdirSync(dest,{recursive:true});fs.writeFileSync(path.join(dest,'index.html'),page(locale,relative,lesson.title+' | '+entry.passage+' | D-Groups',description,body,'Article',imageURL));
  links.push(`<article><h2><a href="${base+relative}">${esc(lesson.title)}</a></h2><p class="passage">${esc(entry.passage)}</p></article>`);
 }
 // Remove only generated week pages that have no currently released public lesson.
 for(const name of fs.readdirSync(directory)){if(!/^week-\d{2}$/.test(name))continue;const relative='devotionals/'+name+'/';if(!urls.includes(relative)){const file=path.join(directory,name,'index.html');if(fs.existsSync(file))fs.unlinkSync(file);}}
 fs.writeFileSync(path.join(directory,'index.html'),page(locale,'devotionals/',t.heading,t.description,`<h1>${t.heading}</h1><p>${t.intro}</p>${links.join('')}`));
 fs.writeFileSync(path.join(root,'discovery.css'),CSS+'\n');
 fs.writeFileSync(path.join(root,'robots.txt'),'User-agent: *\nAllow: /\nDisallow: /.github/\n\nSitemap: '+base+'sitemap.xml\n');
 fs.writeFileSync(path.join(root,'sitemap.xml'),`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">${urls.map(relative=>`<url><loc>${base+relative}</loc>${Object.entries(BASE).map(([lang,b])=>`<xhtml:link rel="alternate" hreflang="${lang}" href="${b+relative}"/>`).join('')}</url>`).join('')}</urlset>\n`);
 for(const name of ['index.html','review.html']){
  const file=path.join(root,name);let html=fs.readFileSync(file,'utf8');
  html=html.replace(/<!-- Search discovery -->[\s\S]*?<!-- \/Search discovery -->/g,'').replace(/<!-- Discovery overview -->[\s\S]*?<!-- \/Discovery overview -->/g,'');
  html=html.replace(/<meta\s+(?:name="robots"|property="og:(?:title|description|url|type|image|locale)"|name="twitter:(?:title|description|image|card)")[^>]*>/g,'').replace(/<link\s+rel="(?:canonical|alternate)"[^>]*>/g,'');
  html=html.replace(/<title>[\s\S]*?<\/title>/,'<title>'+esc(t.title)+'</title>').replace(/<meta name="description"[^>]*>/,'<meta name="description" content="'+esc(t.description)+'">');
  let block=meta(locale,'',t.title,t.description);
  if(name==='review.html')block=block.replace('index, follow, max-image-preview:large','noindex, follow');
  html=html.replace('</head>','<!-- Search discovery -->\n'+block+'\n<link rel="stylesheet" href="./discovery.css?v=20261030-seo">\n<!-- /Search discovery -->\n</head>');
  const overview=`<!-- Discovery overview --><details id="search-overview" class="search-overview"><summary>${t.summary}</summary><p>${t.overview}</p><a href="${base}devotionals/">${t.library} →</a></details><!-- /Discovery overview -->`;
  html=html.replace('<div id="view">',overview+'\n<div id="view">');
  html=html.replace('loading="lazy" decoding="async"></section>','loading="eager" fetchpriority="high" decoding="async"></section>');
  fs.writeFileSync(file,html.replace(/\r\n/g,'\n').replace(/[ \t]+(?=\n)/g,'').replace(/\n{3,}/g,'\n\n'));
 }
 console.log(`Search discovery built (${locale}): ${lessons.length} released commentaries; future weeks excluded.`);
 return ['devotionals','sitemap.xml','robots.txt','discovery.css','index.html','review.html'];
}
if(process.argv[1]&&import.meta.url===pathToFileURL(path.resolve(process.argv[1])).href)buildDiscovery(process.argv[2]||process.cwd());
